import type { VisualEncyclopediaEntry } from './schema';

type GenerationOverride = Pick<VisualEncyclopediaEntry, 'review' | 'media'>;

const score = (
  craft: number,
  composition: number,
  originality: number,
  canonAlignment: number,
  emotionalForce: number,
  accessibility: number,
) => {
  const total = craft + composition + originality + canonAlignment + emotionalForce + accessibility;
  return {
    craft,
    composition,
    originality,
    canonAlignment,
    emotionalForce,
    accessibility,
    total,
    verdict: total >= 26 ? ('ship' as const) : total >= 22 ? ('iterate' as const) : ('restart' as const),
  };
};

const approved = (
  dimensions: [number, number, number, number, number, number],
  media: VisualEncyclopediaEntry['media'],
  notes: string[] = [],
): GenerationOverride => ({
  review: {
    state: 'approved',
    score: score(...dimensions),
    notes,
  },
  media,
});

